<?php
declare(strict_types=1);
$configPath=__DIR__.'/../config/local.php';$schemaPath=__DIR__.'/../database/schema.sql';$done=is_file($configPath);$error='';$success='';function h(string $s):string{return htmlspecialchars($s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
if($_SERVER['REQUEST_METHOD']==='POST'&&!$done){$host=trim($_POST['db_host']??'');$port=(int)($_POST['db_port']??3306);$name=trim($_POST['db_name']??'');$user=trim($_POST['db_user']??'');$pass=(string)($_POST['db_password']??'');$baseUrl=rtrim(trim($_POST['base_url']??''),'/');if(!$host||!$name||!$user||!$baseUrl)$error='Bitte alle Pflichtfelder ausfüllen.';else{try{$dsn="mysql:host={$host};port={$port};dbname={$name};charset=utf8mb4";$pdo=new PDO($dsn,$user,$pass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_EMULATE_PREPARES=>false]);$sql=file_get_contents($schemaPath);if($sql===false)throw new RuntimeException('schema.sql konnte nicht gelesen werden.');$pdo->exec($sql);$cfg=['app'=>['name'=>'Just InCard','base_url'=>$baseUrl,'session_name'=>'justincard_session','timezone'=>'Europe/Berlin'],'db'=>['host'=>$host,'port'=>$port,'name'=>$name,'user'=>$user,'password'=>$pass,'charset'=>'utf8mb4'],'security'=>['token_ttl_days'=>90,'login_window_minutes'=>15,'login_max_attempts'=>8]];$content="<?php\ndeclare(strict_types=1);\nreturn ".var_export($cfg,true).";\n";if(file_put_contents($configPath,$content,LOCK_EX)===false)throw new RuntimeException('config/local.php konnte nicht geschrieben werden. Prüfe die Schreibrechte des config-Ordners.');@chmod($configPath,0600);$success='Installation erfolgreich. Du kannst jetzt dein erstes Konto erstellen.';$done=true;}catch(Throwable $e){$error='Installation fehlgeschlagen: '.$e->getMessage();}}}
?>
<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Just InCard Installation</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><section class="panel install"><span class="eyebrow">Just InCard Webspace</span><h1>Installation</h1><p class="subtle">Verbinde die Webseite mit deiner IONOS-MariaDB. Die Zugangsdaten findest du im IONOS-Konto unter Hosting → Datenbanken.</p><?php if($error):?><div class="alert alert-error"><?=h($error)?></div><?php endif;?><?php if($success):?><div class="alert alert-ok"><?=h($success)?></div><a class="btn btn-primary" href="../register.php">Konto erstellen</a><?php elseif($done):?><div class="alert alert-ok">Just InCard ist bereits installiert.</div><a class="btn btn-primary" href="../index.php">Zur Webseite</a><?php else:?><form method="post"><div class="form-row"><label>Webseiten-URL *</label><input class="input" name="base_url" required placeholder="https://deinedomain.de"></div><div class="form-row"><label>Datenbank-Host *</label><input class="input" name="db_host" required placeholder="db123456.hosting-data.io"></div><div class="form-row"><label>Port</label><input class="input" name="db_port" type="number" value="3306"></div><div class="form-row"><label>Datenbankname *</label><input class="input" name="db_name" required></div><div class="form-row"><label>Datenbankbenutzer *</label><input class="input" name="db_user" required></div><div class="form-row"><label>Datenbankpasswort</label><input class="input" name="db_password" type="password"></div><button class="btn btn-primary" type="submit">Datenbank verbinden & installieren</button></form><?php endif;?></section></body></html>
